from enum import Enum, unique
from typing import List, Optional  # noqa: F401

from .connection_details import (SshServiceDetails)  # noqa: F401
from .optical_switch import SwitchChannel  # noqa: F401
from .pdu import PduPort  # noqa: F401
from .radio import RU  # noqa: F401
from .testpc import TestPc  # noqa: F401


@unique
class FhsType(Enum):
    MDEA = 'MDEA'
    MDCA = 'MDCA'
    MDCB = 'MDCB'
    MDCE = 'MDCE'
    MDCD = 'MDCD'


class FHS(object):
    """Fronthaul Switch attached to the testline. Both indoor and outdoor FHS types are included."""

    def __init__(self,
                 fhs_type,  # type: str
                 pdu_port,  # type: PduPort
                 default_ssh_connection_details=None,  # type: Optional[SshServiceDetails]
                 lmp_connection=None,  # type: Optional[SshServiceDetails]
                 test_pc=None,  # type: Optional[TestPc]
                 optical_switch_channels=None,  # type: Optional[List[SwitchChannel]]
                 serial_number=None,  # type: Optional[str]
                 product_code=None,  # type: Optional[str]
                 rus=None  # type: Optional[List[RU]]
                 ):
        """

        :param Optional[str] fhs_type: str type (unique identifier) of the FHS, should be one of FhsTypes' attributes
        :param PduPort pdu_port: PduPort class instance object, mandatory parameter
        :param Optional[SshServiceDetails] default_ssh_connection_details: SshServiceDetails class instance object
        :param Optional[SshServiceDetails] lmp_connection: SshServiceDetails class instance object
        :param Optional[TestPc] test_pc: test pc details for logs collection via direct lmp_connection
        :param Optional[List[SwitchChannel]] optical_switch_channels: optical switch channels connected to FHS
        :param Optional[str] serial_number: serial number of FHS
        :param Optional[str] product_code: product code of FHS
        :param Optional[List[RU]] rus: rus to which FHS is connected
        """

        self.fhs_type = fhs_type
        self.pdu_port = pdu_port
        self.default_ssh_connection_details = default_ssh_connection_details
        self.lmp_connection = lmp_connection
        self.test_pc = test_pc
        self.optical_switch_channels = optical_switch_channels
        self.serial_number = serial_number
        self.product_code = product_code
        self.rus = rus
